using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.IO;
public static class InstallLabShades {
static GameObject Part(string name,Transform parent,Vector3 pos,Vector3 size,Material mat){var o=GameObject.CreatePrimitive(PrimitiveType.Cube);o.name=name;o.transform.SetParent(parent,false);o.transform.localPosition=pos;o.transform.localScale=size;o.GetComponent<Renderer>().sharedMaterial=mat;return o;}
public static void Run(){if(EditorApplication.isPlaying||Lightmapping.isRunning)throw new System.Exception("Idle required");var original=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path;var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Labs/Upgrade/Materials/White.mat");try{foreach(var room in new[]{"Physics","Chemistry","Biology","Engineering"}){var scene=EditorSceneManager.OpenScene("Assets/Labs/Scenes/"+room+".unity");if(Object.FindAnyObjectByType<LabShade>())continue;bool east=room=="Physics"||room=="Chemistry";float width=room=="Physics"?1.6f:room=="Chemistry"?.65f:1.4f,height=room=="Physics"?1.25f:1;var p=room=="Physics"?new Vector3(4.74f,2.4f,2.05f):room=="Chemistry"?new Vector3(4.14f,2.25f,2.325f):new Vector3(room=="Biology"?2.35f:1.75f,2.3f,room=="Biology"?3.74f:3.54f);
var root=new GameObject("Working roller shade");root.transform.SetPositionAndRotation(p,Quaternion.Euler(0,east?-90:180,0));var shade=root.AddComponent<LabShade>();shade.width=width+.025f;shade.fullDrop=height+.07f;shade.fabric=Part("Opaque shade fabric",root.transform,new Vector3(0,-.0125f,.075f),new Vector3(shade.width,.025f,.006f),mat).transform;Object.DestroyImmediate(shade.fabric.GetComponent<Collider>());
Part("Slim roller cassette",root.transform,new Vector3(0,.015f,.065f),new Vector3(width+.08f,.055f,.085f),mat);
Part("Shade pull cord",root.transform,new Vector3(width/2+.04f,-.30f,.10f),new Vector3(.006f,.6f,.006f),mat);
var handle=Part("Shade pull control",root.transform,new Vector3(width/2+.04f,-.61f,.10f),new Vector3(.04f,.055f,.025f),mat);var hit=handle.GetComponent<BoxCollider>();hit.size=new Vector3(3,2.5f,4);var action=handle.AddComponent<LabFixture>();action.action=LabFixture.Action.Shade;action.shade=shade;action.label="Lower / raise window shade";
shade.Toggle();shade.Step(10);if(Mathf.Abs(shade.fabric.localScale.y-shade.fullDrop)>.001f)throw new System.Exception("Shade failed to lower");shade.Toggle();shade.Step(10);if(Mathf.Abs(shade.fabric.localScale.y-.025f)>.001f)throw new System.Exception("Shade failed to raise");PrefabUtility.SaveAsPrefabAsset(root,"Assets/Labs/Upgrade/"+room+"Shade.prefab");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Debug.Log(room+" shade installed and toggle test passed");}}finally{EditorSceneManager.OpenScene(original);}File.WriteAllText("../Evidence/shade-checks.txt","PASS: four room shades lower to planned drop and retract. Runtime cloth shadows only; baked indirect daylight is fixed. Pointer reach checked separately.");}}
